const ehSabado = diaSemanaNum === 6;

const total = eventosManha.length + eventosTarde.length;

const nomeAtendente = $('Carregar Negócio p/ Relatório').first().json.nome_atendente_ia || 'Assistente';
const nomeEmpresa = $('Carregar Negócio p/ Relatório').first().json.nome_empresa || 'Empresa';

let relatorio = `📋 *RELATÓRIO DA AGENDA*\n`;
relatorio += `📅 *${diaNome}, ${dataFormatada}*\n`;
relatorio += `━━━━━━━━━━━━━━━━━━━━\n\n`;

relatorio += `☀️ *MANHÃ (8h às 12h)*\n`;
if (eventosManha.length > 0) {
  relatorio += eventosManha.join('\n') + '\n';
} else {
  relatorio += `   ✅ Nenhum agendamento\n`;
}

if (ehSabado) {
  relatorio += `\n⚠️ *Sábado: atendimento até 14h*\n`;
} else {
  relatorio += `\n🌙 *TARDE (14h às 20h)*\n`;
  if (eventosTarde.length > 0) {
    relatorio += eventosTarde.join('\n') + '\n';
  } else {
    relatorio += `   ✅ Nenhum agendamento\n`;
  }
}

relatorio += `\n━━━━━━━━━━━━━━━━━━━━\n`;
relatorio += `📊 *Total: ${total} agendamento${total !== 1 ? 's' : ''}*\n`;
relatorio += `\n💜 ${nomeAtendente} — ${nomeEmpresa}`;

return [{ json: { relatorio, total, data: dataFormatada } }];

const raw = $input.first().json;
const body = raw.body || raw;

const evento = (body?.event || '').toLowerCase();
const fromMe = body?.data?.key?.fromMe ?? false;
const remoteJid = body?.data?.key?.remoteJid || '';
const participant = body?.data?.key?.participant || '';
const messageId = body?.data?.key?.id || '';
const instance = body?.instance || body?.instanceName || '';

const msg = body?.data?.message || {};
const text = msg.conversation || msg.extendedTextMessage?.text || '';
const hasContent = !!(text || msg.audioMessage || msg.imageMessage || msg.documentMessage);
const pushName = body?.data?.pushName || '';

const isMessage = evento.includes('messages');
const isGroup = remoteJid.endsWith('@g.us');
const isComando = text.trim().startsWith('#');

// Deixa passar se:
// 1. É mensagem (messages.upsert)
// 2. Não é grupo
// 3. Tem conteúdo OU é fromMe (para processar trava de humano)
if (!isMessage || isGroup) {
  return [];
}

// Se não tem conteúdo E não é fromMe E não é comando, descarta
if (!hasContent && !fromMe && !isComando) {
  return [];
}

return [{
  json: {
    instance: String(instance),
    remoteJid,
    telefone: remoteJid.replace(/@s\.whatsapp\.net$/, ''),
    text,
    pushName,
    fromMe,
    evento,
    messageId,
    body
  }
}];

// ============================================
// NÓ DECISOR CENTRAL — Trava Humano v3
// ============================================
// Analisa a mensagem e define _acao:
//   'comando_parar'     → ativa trava
//   'comando_continuar' → desativa trava
//   'humano_falou'      → ativa trava
//   'cliente_falou'     → segue fluxo normal
// ============================================

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const text = (data.text || '').trim().toLowerCase();
  const fromMe = data.fromMe === true;

  let acao = 'cliente_falou';

  if (text.includes('#parar')) {
    acao = 'comando_parar';
  } else if (text.includes('#continuar')) {
    acao = 'comando_continuar';
  } else if (fromMe) {
    acao = 'humano_falou';
  }

  results.push({ json: { ...data, _acao: acao } });
}

return results;
